### 6. Add API Endpoints to Server Program.cs

Add API endpoints in the server `Program.cs` AFTER `app.MapAdditionalIdentityEndpoints();` and BEFORE `app.Run();`:

```csharp
// Shipment API endpoints
var shipmentApi = app.MapGroup("api/shipments").RequireAuthorization();

shipmentApi.MapGet("/", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()));

shipmentApi.MapGet("/{id:int}", async (int id, IShipmentService service) =>
    await service.GetByIdAsync(id) is { } shipment ? Results.Ok(shipment) : Results.NotFound());

shipmentApi.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
    await service.GetByTrackingNumberAsync(trackingNumber) is { } shipment ? Results.Ok(shipment) : Results.NotFound());

shipmentApi.MapPut("/{id:int}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
{
    await service.UpdateStatusAsync(id, status);
    return Results.NoContent();
});

shipmentApi.MapPost("/", async (Shipment shipment, IShipmentService service) =>
{
    var created = await service.CreateShipmentAsync(shipment);
    return Results.Created($"api/shipments/{created.Id}", created);
});
```

