<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="text-center py-4">
    <h1>Shipment Tracker</h1>
    <p class="lead">Track your shipments in real time</p>
</div>

<div class="row justify-content-center">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Track a Shipment</h5>
                <div class="input-group">
                    <input type="text" class="form-control" placeholder="Enter tracking number (e.g. ST-20260701-12345)"
                           @bind="trackingNumber" @bind:event="oninput"
                           @onkeydown="HandleKeyDown" />
                    <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                        Track
                    </button>
                </div>
                @if (notFound)
                {
                    <div class="alert alert-warning mt-3">No shipment found with that tracking number.</div>
                }
            </div>
        </div>
    </div>
</div>

<AuthorizeView>
    <Authorized>
        <div class="row justify-content-center mt-4">
            <div class="col-md-6 text-center">
                <a href="dashboard" class="btn btn-outline-primary me-2">Dispatcher Dashboard</a>
                <a href="my-shipments" class="btn btn-outline-secondary">My Shipments</a>
            </div>
        </div>
    </Authorized>
</AuthorizeView>

@code {
    private string trackingNumber = string.Empty;
    private bool notFound;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        notFound = false;

        var shipment = await ShipmentService.GetByTrackingNumberAsync(trackingNumber.Trim());
        if (shipment is null)
        {
            notFound = true;
        }
        else
        {
            Navigation.NavigateTo($"shipment/{shipment.TrackingNumber}");
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }
}

