@page "/shipment/{TrackingNumber}"
@attribute [Authorize]
@inject IShipmentService ShipmentService
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (shipment is null)
{
    @if (loading)
    {
        <p><em>Loading shipment details...</em></p>
    }
    else
    {
        <div class="alert alert-warning">Shipment not found.</div>
    }
}
else
{
    <h2>Shipment @shipment.TrackingNumber</h2>

    <div class="row mt-3">
        <div class="col-md-6">
            <div class="card">
                <div class="card-header">Shipment Details</div>
                <div class="card-body">
                    <dl class="row mb-0">
                        <dt class="col-sm-5">Origin</dt>
                        <dd class="col-sm-7">@shipment.Origin</dd>
                        <dt class="col-sm-5">Destination</dt>
                        <dd class="col-sm-7">@shipment.Destination</dd>
                        <dt class="col-sm-5">Status</dt>
                        <dd class="col-sm-7"><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></dd>
                        <dt class="col-sm-5">Created</dt>
                        <dd class="col-sm-7">@shipment.CreatedDate.ToString("MMM dd, yyyy")</dd>
                        <dt class="col-sm-5">Estimated Delivery</dt>
                        <dd class="col-sm-7">@(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</dd>
                        @if (!string.IsNullOrWhiteSpace(shipment.Notes))
                        {
                            <dt class="col-sm-5">Notes</dt>
                            <dd class="col-sm-7">@shipment.Notes</dd>
                        }
                    </dl>
                </div>
            </div>
        </div>

        <div class="col-md-6">
            <div class="card">
                <div class="card-header">Status Timeline</div>
                <div class="card-body">
                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                    {
                        var reached = (int)status <= (int)shipment.Status && shipment.Status != ShipmentStatus.Cancelled;
                        <div class="d-flex align-items-center mb-2">
                            <span class="me-2">@(reached ? "✅" : "⬜")</span>
                            <span class="@(reached ? "fw-bold" : "text-muted")">@status</span>
                        </div>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private Shipment? shipment;
    private bool loading = true;

    protected override async Task OnParametersSetAsync()
    {
        loading = true;
        shipment = await ShipmentService.GetByTrackingNumberAsync(TrackingNumber);
        loading = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit or ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/dashboard"
@attribute [Authorize]
@inject IShipmentService ShipmentService
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Dispatcher Dashboard</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="destinationFilter" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-success" @onclick="() => showCreateForm = !showCreateForm">
            @(showCreateForm ? "Cancel" : "+ New Shipment")
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-header">Create New Shipment</div>
        <div class="card-body">
            <div class="row g-3">
                <div class="col-md-3">
                    <label class="form-label">Origin</label>
                    <input type="text" class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Destination</label>
                    <input type="text" class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Customer Email</label>
                    <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Est. Delivery</label>
                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-12">
                    <label class="form-label">Notes</label>
                    <input type="text" class="form-control" @bind="newShipment.Notes" />
                </div>
                <div class="col-12">
                    <button class="btn btn-primary" @onclick="CreateShipment"
                            disabled="@(string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination))">
                        Create Shipment
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Customer</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td><a href="shipment/@s.TrackingNumber">@s.TrackingNumber</a></td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td>
                        <select class="form-select form-select-sm" value="@s.Status"
                                @onchange="e => UpdateStatus(s, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status" selected="@(status == s.Status)">@status</option>
                            }
                        </select>
                    </td>
                    <td>@(s.CustomerEmail ?? "—")</td>
                    <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</td>
                    <td>
                        <a href="shipment/@s.TrackingNumber" class="btn btn-sm btn-outline-primary">View</a>
                    </td>
                </tr>
            }
        </tbody>
    </table>

    @if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments match the current filters.</div>
    }
}

@code {
    private List<Shipment>? shipments;
    private string destinationFilter = string.Empty;
    private string statusFilter = string.Empty;
    private bool showCreateForm;
    private Shipment newShipment = new();

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? [])
            .Where(s => string.IsNullOrWhiteSpace(destinationFilter) ||
                        s.Destination.Contains(destinationFilter, StringComparison.OrdinalIgnoreCase))
            .Where(s => string.IsNullOrWhiteSpace(statusFilter) ||
                        s.Status.ToString() == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private async Task CreateShipment()
    {
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments?.Insert(0, created);
        newShipment = new();
        showCreateForm = false;
    }
}

